return {["scripts/actions/abilities/ignis.lua"]={["Path"]="scripts/actions/abilities/ignis.lua",["SHA256"]="979addf6e5211f97c812aeb31a286221f4b00246796150932617fdb1ff673d27",["Text"]="-----------------------------------\n-- Ability: Ignis\n-- Increases resistance against ice and deals fire damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.IGNIS)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/immanence.lua"]={["Path"]="scripts/actions/abilities/immanence.lua",["SHA256"]="3664b148d45b2ad2effff69ccc1e80f8cc2f140ada34cee4e425d4295bbbf16a",["Text"]="-----------------------------------\n-- Ability: Immanence\n-- Makes it possible for your next elemental magic spell to be used in a skillchain, but not a magic burst.\n-- Obtained: Scholar Level 87\n-- Duration: 1 Black Magic Spell or 60 seconds, whichever occurs first.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.IMMANENCE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.IMMANENCE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.IMMANENCE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/impetus.lua"]={["Path"]="scripts/actions/abilities/impetus.lua",["SHA256"]="0b00441308525e1f56dc244004884b1a71109a240e28e710805f5824a3735aba",["Text"]="-----------------------------------\n-- Ability: Impetus\n-- Description: Enhances attack and critical hit rate with each successive melee attack you land.\n-- Obtained: MNK Level 88\n-- Recast Time: 00:05:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useImpetus(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/inner_strength.lua"]={["Path"]="scripts/actions/abilities/inner_strength.lua",["SHA256"]="7fa164b62928577fb4bea74eb6b0e52e10329405b764199b4f363a27d848e945",["Text"]="-----------------------------------\n-- Ability: Inner Strength\n-- Description: Increases your maximum HP.\n-- Obtained: MNK Level 96\n-- Recast Time: 01:00:00\n-- Duration: 0:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.monk.checkInnerStrength(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useInnerStrength(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/innin.lua"]={["Path"]="scripts/actions/abilities/innin.lua",["SHA256"]="7ea331ad5f4bd4e550a610d1434dcb493ff1e947e70dd68d0bf8c9577ce15e05",["Text"]="-----------------------------------\n-- Ability: Innin\n-- Reduces enmity and impairs evasion. Grants a bonus to accuracy, critical hit rate, and ninjutsu damage when striking target from behind.\n-- Obtained: Ninja Level 40\n-- Recast Time: 3:00\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkInnin(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useInnin(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/intervene.lua"]={["Path"]="scripts/actions/abilities/intervene.lua",["SHA256"]="d7e56291a371a69920323c84bb05825e691fbf6a3fad490ae22600df4d023000",["Text"]="-----------------------------------\n-- Ability: Intervene\n-- Description: Strikes the target with your shield and decreases its attack and accuracy.\n-- Obtained: PLD Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.paladin.checkIntervene(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useIntervene(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/invincible.lua"]={["Path"]="scripts/actions/abilities/invincible.lua",["SHA256"]="98179ac0b6e6eabf856aab126c2e8d44816859cf9d6fd4f5a5385a0bac76a930",["Text"]="-----------------------------------\n-- Ability: Invincible\n-- Grants immunity to all physical attacks.\n-- Obtained: Paladin Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.paladin.checkInvincible(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useInvincible(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/issekigan.lua"]={["Path"]="scripts/actions/abilities/issekigan.lua",["SHA256"]="7c8a2e78ba33377fb00e5efb44b54e3c4006ab38d72bf8e8fd3978dd821e8575",["Text"]="-----------------------------------\n-- Ability: Issekigan\n-- Increases Chance of parrying and gives an enmity bonus upon a successful parry attempt.\n-- Obtained: Ninja Level 95\n-- Recast Time: 5:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkIssekigan(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useIssekigan(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/jump.lua"]={["Path"]="scripts/actions/abilities/jump.lua",["SHA256"]="3648b9543e75b23be9814c808cebbd63783f92ddefb83a4abc0d6cb114b3a861",["Text"]="-----------------------------------\n-- Ability: Jump\n-- Delivers a short jumping attack on a targeted enemy.\n-- Obtained: Dragoon Level 10\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useJump(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/killer_instinct.lua"]={["Path"]="scripts/actions/abilities/killer_instinct.lua",["SHA256"]="a7437f36b3be82992b83f6622b931d1f91d5d26b62ed353e73f8835410ed28b2",["Text"]="-----------------------------------\n-- Ability: Killer Instinct\n-- Grants your pet's Killer Effect to party members within area of effect.\n-- Obtained: Beastmaster Level 75 (Merit)\n-- Recast Time: 5:00\n-- Duration: 3:00\n-----------------------------------\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkKillerInstinct(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useKillerInstinct(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/konzen-ittai.lua"]={["Path"]="scripts/actions/abilities/konzen-ittai.lua",["SHA256"]="682668001280bacafb36a449687df135fcf736070820f8b16b3492a706e9f74c",["Text"]="-----------------------------------\n-- Ability: Konzen-Ittai\n-- Readies target for a skillchain.\n-- Obtained: Samurai Level 65\n-- Recast Time: 0:03:00\n-- Duration: 1:00 or until next Weapon Skill\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.samurai.checkKonzenIttai(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.samurai.useKonzenIttai(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/larceny.lua"]={["Path"]="scripts/actions/abilities/larceny.lua",["SHA256"]="692882e84c37d87d41a1586c90373d924928e058bee1f01b71e4cf004acc8f00",["Text"]="-----------------------------------\n-- Ability: Larceny\n-- Description: Steals one beneficial effect from the target enemy.\n-- Obtained: THF Level 96\n-- Recast Time: 01:00:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.thief.checkLarceny(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.thief.useLarceny(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/last_resort.lua"]={["Path"]="scripts/actions/abilities/last_resort.lua",["SHA256"]="321e89928fa4d10ec5c054dd1cab2119e83b17b2306b77b8acbc3edf11625beb",["Text"]="-----------------------------------\n-- Ability: Last Resort\n-- Description: Increases user's attack, but lowers defense.\n-- Obtained: Dark Knight Level 15\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useLastResort(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/lasting_emanation.lua"]={["Path"]="scripts/actions/abilities/lasting_emanation.lua",["SHA256"]="062672ce8fa1439e4426c12bc362458dd09ad4c6ede5d2387efc8600e4c56cf7",["Text"]="-----------------------------------\n-- Ability: Lasting Emanation\n-- Reduces the amount of HP your luopan consumes.\n-- Obtained: Geomancer Level 25\n-- Recast Time: 00:05:00\n-- Duration: N/A\n-- Notes: Base HP drain rate is 24 HP/tic. With Lasting Emenation it is 17HP/tic.\n-- Operates on a shared recast timer with Ecliptic Attrition.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    xi.job_utils.geomancer.lastingEmanation(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/leave.lua"]={["Path"]="scripts/actions/abilities/leave.lua",["SHA256"]="89dcfbdd538cba5423201336ce44336d321b3268d25dbef18b940cb4820e25fe",["Text"]="-----------------------------------\n-- Ability: Leave\n-- Sets your pet free.\n-- Obtained: Beastmaster Level 35\n-- Recast Time: 10 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkPetCommand(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useLeave(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/libra.lua"]={["Path"]="scripts/actions/abilities/libra.lua",["SHA256"]="e4d9eb88fb46373f75dfe7e5fcfc76384750d195e5fa29ecb0546b6e48387c02",["Text"]="-----------------------------------\n-- Ability: Libra\n-- Description: Examines the target's enmity level.\n-- Obtained: SCH Level 76\n-- Recast Time: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- player:addStatusEffect(xi.effect.LIBRA, { power = 20, duration = 1, origin = player, tick = 1 }) -- TODO: implement xi.effect.LIBRA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/liement.lua"]={["Path"]="scripts/actions/abilities/liement.lua",["SHA256"]="93949be22d737fc6704d7910f4b5a1ea2427dce8193a74d6642a363a74e3fac3",["Text"]="-----------------------------------\n-- Ability: Liement\n-- Absorbs elemental damage. The types of elemental damage absorbed depend on the runes you harbor.\n-- Obtained: Rune Fencer Level 85\n-- Recast Time: 3:00\n-- Duration: 10 seconds or first absorb\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useLiement(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/life_cycle.lua"]={["Path"]="scripts/actions/abilities/life_cycle.lua",["SHA256"]="ea4eba19fdd40b5437193f683780b22a342a0beeea8f783382ddf566024238e1",["Text"]="-----------------------------------\n-- Ability: Life Cycle\n-- Distributes one fourth of your HP to your luopan.\n-- Obtained: Geomancer Level 50\n-- Recast Time: 10 minutes\n-- Grants your luopan 25% of your current HP.\n-- The HP lost is not affected by gear or job points.\n-- You also subsequently cannot kill yourself using this JA.\n-- The increase in Life Cycle potency from Job points is applied in the same set as equipment bonuses.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnLifeCycleAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.geomancer.lifeCycle(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/light_arts.lua"]={["Path"]="scripts/actions/abilities/light_arts.lua",["SHA256"]="f3bfa70c09775fa747067b9c38ebd02530021c0bcc983d63ecb0551944a17765",["Text"]="-----------------------------------\n-- Ability: Light Arts\n-- Optimizes white magic capability while lowering black magic proficiency. Grants a bonus to divine, enhancing, enfeebling, and healing magic. Also grants access to Stratagems.\n-- Obtained: Scholar Level 10\n-- Recast Time: 1:00\n-- Duration: 2:00:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if\n        player:hasStatusEffect(xi.effect.LIGHT_ARTS) or\n        player:hasStatusEffect(xi.effect.ADDENDUM_WHITE)\n    then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:delStatusEffectSilent(xi.effect.DARK_ARTS)\n    player:delStatusEffect(xi.effect.ADDENDUM_BLACK)\n    player:delStatusEffect(xi.effect.PARSIMONY)\n    player:delStatusEffect(xi.effect.ALACRITY)\n    player:delStatusEffect(xi.effect.MANIFESTATION)\n    player:delStatusEffect(xi.effect.EBULLIENCE)\n    player:delStatusEffect(xi.effect.FOCALIZATION)\n    player:delStatusEffect(xi.effect.EQUANIMITY)\n    player:delStatusEffect(xi.effect.IMMANENCE)\n\n    local effectbonus = player:getMod(xi.mod.LIGHT_ARTS_EFFECT)\n    local regenbonus  = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        regenbonus = 3 * math.floor((player:getMainLvl() - 10) / 10)\n    end\n\n    player:addStatusEffect(xi.effect.LIGHT_ARTS, { power = effectbonus, duration = 7200, origin = player, subPower = regenbonus })\n\n    return xi.effect.LIGHT_ARTS\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/light_maneuver.lua"]={["Path"]="scripts/actions/abilities/light_maneuver.lua",["SHA256"]="4e9a0c5787a0bcaf7750d6ae2804971648c7c0b163cc708bdcf451c3c756987f",["Text"]="-----------------------------------\n-- Ability: Light Maneuver\n-- Enhances the effect of light attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/light_shot.lua"]={["Path"]="scripts/actions/abilities/light_shot.lua",["SHA256"]="30b38c1240217ff5817702955f652d665f307b880f3598f6088736ade1590d66",["Text"]="-----------------------------------\n-- Ability: Light Shot\n-- Consumes a Light Card to enhance light-based debuffs. Additional effect: Light-based Sleep\n-- Dia Effect: Defense Down Effect +5% and DoT + 1\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/lunge.lua"]={["Path"]="scripts/actions/abilities/lunge.lua",["SHA256"]="70727038d4373a08785b8e0fbdcf35c15d0dc51987fc143f6aea97c52b0561c0",["Text"]="-----------------------------------\n-- Ability: Lunge\n-- Expends all runes to deal damage to a target.\n-- Obtained: Rune Fencer Level 25\n-- Recast Time: 3:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:getAnimation() ~= 1 then\n        return xi.msg.basic.REQUIRES_COMBAT, 0\n    end\n\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useSwipeLunge(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/lux.lua"]={["Path"]="scripts/actions/abilities/lux.lua",["SHA256"]="286807f978a279745b6ff650804d24f8b7169d23ebfb811b4729cd7faa3b1e2f",["Text"]="-----------------------------------\n-- Ability: Lux\n-- Increases resistance against dark and deals light damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.LUX)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/maguss_roll.lua"]={["Path"]="scripts/actions/abilities/maguss_roll.lua",["SHA256"]="f206df052ac48617cf7596be3ed09c73ad11f6b12a0b54f9c6a7266aa6a9411c",["Text"]="-----------------------------------\n-- Ability: Magus's Roll\n-- Enhances magic defense for party members within area of effect\n-- Optimal Job: Blue Mage\n-- Lucky Number: 2\n-- Unlucky Number: 6\n-- Level: 17\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    |No BLU  |With BLU\n-----------    -------  -----------\n-- 1           |+5      |+13\n-- 2           |+20     |+28\n-- 3           |+6      |+14\n-- 4           |+8      |+16\n-- 5           |+9      |+17\n-- 6           |+3      |+11\n-- 7           |+10     |+18\n-- 8           |+13     |+21\n-- 9           |+14     |+22\n-- 10          |+15     |+23\n-- 11          |+25     |+33\n-- Bust        |-5      |-5\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/maintenance.lua"]={["Path"]="scripts/actions/abilities/maintenance.lua",["SHA256"]="d7e7d2e5659b6fd9ab3ed288fa8d01032d3888245373bfd1c88c767565ffcbbb",["Text"]="-----------------------------------\n-- Ability: Maintenance\n-- Cures your automaton of status ailments. Special items required\n-- Obtained: Puppetmaster Level 30\n-- Recast Time: 1:30\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckMaintenance(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseMaintenance(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/majesty.lua"]={["Path"]="scripts/actions/abilities/majesty.lua",["SHA256"]="ef24f81264322d527974c4754e775d09703486c8dd573b0051fb84cc62269f44",["Text"]="-----------------------------------\n-- Ability: Majesty\n-- Description: Increases Cure potency and reduces Cure recast time. Additionally, causes Cure and Protect spells to affect party members in area of effect.\n-- Obtained: PLD Level 70\n-- Recast Time: 00:01:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useMajesty(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mana_cede.lua"]={["Path"]="scripts/actions/abilities/mana_cede.lua",["SHA256"]="16f8d15099a25e1766e07cc6eb55b81fc28ecafc787c92caa3aafd94b74a1014",["Text"]="-----------------------------------\n-- Ability: Mana Cede\n-- Description: Channels your MP into TP for avatars and elementals.\n-- Obtained: SMN Level 87\n-- Recast Time: 00:05:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local playerMP = player:getMP()\n    local avatar   = player:getPet()\n\n    -- Retail only checks if you have an avatar summoned, but we can do better.\n    -- Actual behavior: Ability can still be used at 3000 TP and < 100 MP.\n    -- Results in player expending the rest of their MP and subsequently dismissing avatar.\n    if avatar ~= nil then\n        local avatarTP = avatar:getTP()\n        if avatarTP == 3000 or playerMP < 100 then\n            return xi.msg.basic.UNABLE_TO_USE_JA, 0\n        end\n    elseif avatar == nil then\n        return xi.msg.basic.REQUIRES_A_PET, 0\n    end\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    xi.job_utils.summoner.useManaCede(player, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mana_wall.lua"]={["Path"]="scripts/actions/abilities/mana_wall.lua",["SHA256"]="125a1aa491daaf3e6afd7b9c79f12e94f000ce7531e8389e3e0a23b1113f11bb",["Text"]="-----------------------------------\n-- Ability: Mana Wall\n-- Description: Allows you to take damage with MP.\n-- Obtained: BLM Level 76\n-- Recast Time: 00:10:00\n-- Duration: 00:05:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useManaWall(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/manafont.lua"]={["Path"]="scripts/actions/abilities/manafont.lua",["SHA256"]="3e04b8a965608837d2e6ffc8679847031a54bdc5f1bce58daab4f8d41466ad74",["Text"]="-----------------------------------\n-- Ability: Manafont\n-- Eliminates the cost of magic spells.\n-- Obtained: Black Mage Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.black_mage.checkManafont(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useManafont(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/manawell.lua"]={["Path"]="scripts/actions/abilities/manawell.lua",["SHA256"]="822350522e91c335084cd17c572a5289fa0ba5c8f2b6b356911263c55e02ee23",["Text"]="-----------------------------------\n-- Ability: Manawell\n-- Description: Eliminates the cost of the next magic spell the target casts.\n-- Obtained: BLM Level 95\n-- Recast Time: 00:10:00 or the next spell cast\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useManawell(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/manifestation.lua"]={["Path"]="scripts/actions/abilities/manifestation.lua",["SHA256"]="cdfee8328e24e241116785100533acc32e19280a430790ca32f680b43e382ca5",["Text"]="-----------------------------------\n-- Ability: Manifestation\n-- Extends the effect of your next enfeebling1 black magic spell to targets within range. MP cost and casting time2 are doubled.\n-- Obtained: Scholar Level 40\n-- Recast Time: Stratagem Charge\n-- Duration: 1 compatible black magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.MANIFESTATION) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.MANIFESTATION, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.MANIFESTATION\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mantra.lua"]={["Path"]="scripts/actions/abilities/mantra.lua",["SHA256"]="954d8365b3ee61b112a691b92583228af714ca93117017d0eb8b06677b320e85",["Text"]="-----------------------------------\n-- Ability: Mantra\n-- Increases the max. HP of party members within area of effect.\n-- Obtainable: Monk Level 75\n-- Recast Time: 0:10:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useMantra(player, target, ability)\nend\n\nreturn abilityObject\n"}};
